protocol Greeter { func greet(name: String) -> String }
struct FriendlyGreeter: Greeter { func greet(name: String) -> String { "Hello, \(name)!" } }
final class WelcomeController {
    let greeter: Greeter
    init(greeter: Greeter) { self.greeter = greeter }
}
