print(c.greeter.greet(name: "Taylor"))

protocol DiscountStrategy { func apply(to price: Double) -> Double }
struct HalfPrice: DiscountStrategy { func apply(to price: Double) -> Double { price * 0.5 } }
final class CartManager {
    let strategy: DiscountStrategy
    init(strategy: DiscountStrategy) { self.strategy = strategy }
}
let c = CartManager(strategy: HalfPrice())
print(Int(c.strategy.apply(to: 80)))

