protocol Notifier { func message() -> String }
struct DefaultNotifier: Notifier { func message() -> String { "Standard Alert" } }
struct CustomNotifier: Notifier { func message() -> String { "Urgent Alert" } }
final class AlertService {
    let notifier: Notifier
    init(notifier: Notifier = DefaultNotifier()) { self.notifier = notifier }
}
let s = AlertService(notifier: CustomNotifier())
print(s.notifier.message())

protocol ActionLogger: AnyObject { var count: Int { get set }; func record() }
final class SpyLogger: ActionLogger {
    var count = 0
    func record() { count += 1 }
}
final class ButtonAction {
    let logger: ActionLogger
    init(logger: ActionLogger) { self.logger = logger }
    func tap() { logger.record(); logger.record() }
}
let spy = SpyLogger()
let btn = ButtonAction(logger: spy)
btn.tap()
print(spy.count)

protocol CacheStorage { func read() -> String? }
struct MemoryCache: CacheStorage { func read() -> String? { "CachedData" } }
final class DataLoader {
    let cache: CacheStorage
    init(cache: CacheStorage) { self.cache = cache }
    func load() -> String { cache.read() ?? "RemoteData" }
}
let loader = DataLoader(cache: MemoryCache())
print(loader.load())

